<?php

/* @autogenerated */
declare(strict_types=1);

namespace Tests\integration\Features\OAuth\Stub;

use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationRequest;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationResult;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\ChallengesState;
use Civi\Lughauth\Features\OAuth\User\Domain\Gateway\LoginGateway;

class InMemoryLoginGateway implements LoginGateway
{
    /** @var array<string, array{id: string, name: string, email: string, scope: string}> */
    private array $users = [];

    public function register(string $tenant, string $username, string $password, string $id, string $name, string $email, string $scope = 'openid profile email'): void
    {
        $this->users[$tenant . ':' . $username] = [
            'id' => $id,
            'password' => $password,
            'name' => $name,
            'email' => $email,
            'scope' => $scope,
        ];
    }

    /** @var array<string, true> users (tenant:username) with an enrolled TOTP seed */
    private array $seeds = [];

    public function enrolSecondFactor(string $tenant, string $username): void
    {
        $this->seeds[$tenant . ':' . $username] = true;
    }

    public function mfaEnrolmentPending(string $tenant, string $username, bool $mfaRequested = false): bool
    {
        return $mfaRequested && !isset($this->seeds[$tenant . ':' . $this->usernameOf($tenant, $username)]);
    }

    public function secondFactorChallenge(string $tenant, string $username): AuthenticationResult
    {
        return isset($this->seeds[$tenant . ':' . $this->usernameOf($tenant, $username)])
            ? AuthenticationResult::mfaRequired()
            : AuthenticationResult::newMfaRequired();
    }

    public function usernameOf(string $tenant, string $subject): string
    {
        foreach ($this->users as $key => $entry) {
            if ($key === $tenant . ':' . $subject || $entry['id'] === $subject) {
                return substr($key, strlen($tenant) + 1);
            }
        }
        return $subject;
    }

    public function markSecondFactorFailed(string $tenant, string $username): void
    {
    }

    public function validatedUserData(string $tenant, string $username, string $password, AuthenticationRequest $client): AuthenticationResult
    {
        $entry = $this->users[$tenant . ':' . $username] ?? null;
        if ($entry === null) {
            return AuthenticationResult::unknowUser($tenant, $username);
        }
        if ($entry['password'] !== $password) {
            return AuthenticationResult::wrongCredentials($tenant, $username);
        }
        return new AuthenticationResult(
            valid: true,
            id: $entry['id'],
            tenant: $tenant,
            // Like LoginAdapter: the requested scope, the registered one when none is requested.
            scope: $client->scope !== '' ? $client->scope : $entry['scope'],
            name: $entry['name'],
            email: $entry['email'],
            roles: [],
            groups: [],
        );
    }

    public function fillPreLoadById(string $tenant, AuthenticationRequest $client, ChallengesState $challenges): AuthenticationResult
    {
        $username = $challenges->username ?? '';
        foreach ($this->users as $key => $entry) {
            if ($key === $tenant . ':' . $username || $entry['id'] === $username) {
                return new AuthenticationResult(
                    valid: true,
                    id: $entry['id'],
                    tenant: $tenant,
                    scope: $client->scope !== '' ? $client->scope : $entry['scope'],
                    name: $entry['name'],
                    email: $entry['email'],
                    roles: [],
                    groups: [],
                );
            }
        }
        return AuthenticationResult::unknowUser($tenant, $username);
    }

    public function fillPreAuthenticated(string $tenant, AuthenticationRequest $client, ChallengesState $challenges): AuthenticationResult
    {
        return $this->fillPreLoadById($tenant, $client, $challenges);
    }

    public static function withDefaults(): self
    {
        $gateway = new self();
        $gateway->register(
            tenant: 'tenant1',
            username: 'testuser',
            password: 'testpass',
            id: 'user-123',
            name: 'Test User',
            email: 'test@example.com',
        );
        return $gateway;
    }
}
